import{z as d,x as p,o as l,c as A,q as i,j as s,D as e,d as E,s as n,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"PRG 与 PRF","description":"","frontmatter":{"title":"PRG 与 PRF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/prg-prf.md","filePath":"cs/prg-prf.md","lastUpdated":1791413859000}'),B={name:"cs/prg-prf.md"};function P(R,a,c,F,m,h){const t=p("Mermaid");return l(),A("div",null,[a[2]||(a[2]=i('<h1 id="prg-与-prf" tabindex="-1">PRG 与 PRF <a class="header-anchor" href="#prg-与-prf" aria-label="Permalink to &quot;PRG 与 PRF&quot;">​</a></h1><div class="epigraph"><p>伪随机发生器把短种子拉成对多项式敌手不可区分于均匀的长串；伪随机函数把密钥编成一张看起来随机的函数表。计算安全的对称世界从这里起步。</p><footer>—— 据 Goldreich, Goldwasser and Micali；Blum and Micali；Yao；Katz and Lindell 整理</footer></div><p>上一课<a href="/cs/one-time-pad-perfect-secrecy">一次一密</a>要求等长真随机。缺口是<strong>短密钥如何假装成长随机串</strong>。本课给出 PRG 与 PRF 的游戏语言，不重证 Shannon，也不把 AES 圈函数当定义。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>完善保密禁止压缩密钥。计算安全允许：敌手只跑多项式时间。PRG：\\(G(s)\\) 与均匀 \\(U\\) 不可区分。PRF：带密钥的 \\(F_k\\) 与随机函数不可区分。缺口是这两条原语的合同，不是「随机数库调用一下」。流密码是 PRG 的工程亲戚；分组密码在理想里被当成 PRP，再当 PRF 用。</p><h3 id="游戏而不是「看起来乱」" tabindex="-1">游戏而不是「看起来乱」 <a class="header-anchor" href="#游戏而不是「看起来乱」" aria-label="Permalink to &quot;游戏而不是「看起来乱」&quot;">​</a></h3><p>不可区分是实验：敌手拿到样例，猜「真随机还是伪随机」。可忽略优势才叫安全。把输出打印出来用肉眼看，不是定义。</p><p><span class="marginnote">Goldreich–Goldwasser–Micali 从 PRG 构造 PRF。Yao 把不可区分与下一比特预测连起来。后课 AES 是候选 PRP，本课不把候选当证明。</span></p><p><span class="marginnote">术语翻译：「计算安全」就是把『绝对分不出』降级为『现实的算力在合理时间内分不出』——敌手再聪明，也只能跑多项式时间；无界敌手不在合同范围内。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用「种子进、长串出」画 PRG；用「密钥 + 输入 → 输出」画 PRF。指出：PRF 可造 MAC 与计数器模式；PRG 可造流密码。安全性沿归约走，具体候选下一课。</p>',12)),(l(),s(o,null,{default:e(()=>[n(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%9F%AD%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20PRG%5B%22PRG%22%5D%0A%20%20PRG%20--%3E%20STR%5B%22%E9%95%BF%E4%BC%AA%E9%9A%8F%E6%9C%BA%E4%B8%B2%22%5D%0A%20%20K%5B%22%E5%AF%86%E9%92%A5%22%5D%20--%3E%20PRF%5B%22PRF%22%5D%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20PRF%0A%20%20PRF%20--%3E%20Y%5B%22%E7%9C%8B%E8%B5%B7%E6%9D%A5%E9%9A%8F%E6%9C%BA%E7%9A%84%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"一次一密的 \\(k\\) 被 \\(G(s)\\) 替换后，完善性换成计算不可区分：无界敌手仍可能区分，多项式敌手不能。PRF 比 PRG 多一个输入轴，才能对每条消息、每个 nonce 派生不同的密钥流或标签。",-1)),a[5]||(a[5]=r("p",null,"「不可区分」不是形容词，是一场具体的实验：",-1)),(l(),s(o,null,{default:e(()=>[n(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E6%8C%91%E6%88%98%E8%80%85%E6%8E%B7%E7%A1%AC%E5%B8%81%20b%22%5D%20--%3E%20B0%5B%22b%3D0%EF%BC%9A%E7%BB%99%E6%95%8C%E6%89%8B%E7%9C%9F%E9%9A%8F%E6%9C%BA%E6%A0%B7%E4%BE%8B%22%5D%0A%20%20CH%20--%3E%20B1%5B%22b%3D1%EF%BC%9A%E7%BB%99%E6%95%8C%E6%89%8B%20G(s)%20%E7%9A%84%E8%BE%93%E5%87%BA%22%5D%0A%20%20B0%20--%3E%20ADV%5B%22%E6%95%8C%E6%89%8B%E5%A4%9A%E9%A1%B9%E5%BC%8F%E6%97%B6%E9%97%B4%E8%A7%82%E5%AF%9F%E5%90%8E%E7%8C%9C%20b%22%5D%0A%20%20B1%20--%3E%20ADV%0A%20%20ADV%20--%3E%20WIN%5B%22%E7%8C%9C%E4%B8%AD%E4%BC%98%E5%8A%BF%E5%8F%AF%E5%BF%BD%E7%95%A5%20%E5%88%99%E5%88%A4%E5%AE%9A%E4%B8%8D%E5%8F%AF%E5%8C%BA%E5%88%86%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">数字实例：128 位种子经 PRG 可拉成 1 GB 密钥流去加密大文件；合同说多项式时间的敌手无法把这串输出与真正的 1 GB 随机数区分开——尽管信息论上它只含 128 位熵。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列全部候选数论 PRG，不把 /dev/urandom 的工程当定义。下一课用 AES 把「候选 PRP」落到结构，而不是再讲游戏。后课默认：谈到计算安全的对称构造，先问是 PRG 还是 PRF。</p><p><span class="marginnote">常见误区：肉眼看输出「很乱」就当成随机。安全的定义是游戏优势——不存在多项式时间敌手能以不可忽略的优势猜中；输出长得乱不乱与此毫无关系。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>等长真随机做不到时，用 PRG/PRF 换计算假设。</li><li>PRG 拉长；PRF 是带密钥的随机函数表。</li><li>不可区分是游戏优势，不是视觉杂乱。</li><li>AES 结构是下一课的候选置换，不是本课的证明。</li><li>出处：Goldreich, Goldwasser and Micali；Blum and Micali；Yao；Katz and Lindell。</li></ul>',6))])}const G=d(B,[["render",P]]);export{D as __pageData,G as default};
